import json

# Let me test projecting ALL cells with formula 2 and see overwriting patterns
Demo_H, Demo_W = 26, 24
Demo_non_bg = [(11, 10, 9), (11, 11, 6), (12, 9, 7), (12, 10, 2), (13, 9, 7)]

output = [[8]*Demo_W for _ in range(Demo_H)]

def formula_2(r, c, steps):
    if steps == 1:
        return (r + 1, c)
    else:
        return (r + steps, c - (steps - 1))

# Project from ALL cells (order matters - later cells overwrite earlier)
for r, c, v in Demo_non_bg:
    for step in range(1, 30):
        new_r, new_c = formula_2(r, c, step)
        if 0 <= new_r < Demo_H and 0 <= new_c < Demo_W:
            output[new_r][new_c] = v

print("Projecting ALL cells (order matters):")
for row in [12, 13, 14, 15, 16, 20, 23]:
    non_bg_cells = [(c, output[row][c]) for c in range(Demo_W) if output[row][c] != 8]
    print(f"  Row {row}: {non_bg_cells}")

# Try reverse order - earlier cells overwrite later
output = [[8]*Demo_W for _ in range(Demo_H)]
reverse_cells = list(reversed(Demo_non_bg))

for r, c, v in reverse_cells:
    for step in range(1, 30):
        new_r, new_c = formula_2(r, c, step)
        if 0 <= new_r < Demo_H and 0 <= new_c < Demo_W:
            output[new_r][new_c] = v

print("\nProjecting in REVERSE order (earlier cells overwrite later):")
for row in [12, 13, 14, 15, 16, 20, 23]:
    non_bg_cells = [(c, output[row][c]) for c in range(Demo_W) if output[row][c] != 8]
