] + [[1]*6 for _ in range(20)]

non_bg = [
    (0, 3, 3),
    (1, 4, 3),
    (1, 5, 2),
    (2, 4, 6),
    (2, 5, 2),
]

# Create output grid - start with background, then fill
output = [[1]*W for _ in range(H)]

def formula_2(r, c, steps):
    if steps == 1:
        return (r + 1, c)
    else:
        return (r + steps, c - (steps - 1))

# Step 1: Copy input cells first (they stay)
for r, c, v in non_bg:
    output[r][c] = v

# Step 2: Project ALL cells with formula 2
# Order: start with furthest projections (last ones) to avoid overwriting with nearest first
# Actually, let's try both orders

order = list(non_bg)  # forward: later cells overwrite earlier
