for r, c, v in order:
    for step in range(1, 40):  # enough to go out of bounds
        new_r, new_c = formula_2(r, c, step)
        if 0 <= new_r < H and 0 <= new_c < W:
            output[new_r][new_c] = v
        else:
            break

